-- vendor exclusivity with loose name patterns and NO state filter: does any other 527 pay these vendors under a variant spelling or other address?
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
p AS (SELECT column1 pat FROM VALUES ('%RESIDENTIAL PROG%'),('%BF%TEL%'),('%CAMPAIGN CALLING%'),('%SIMPLE DATA%'),('%ONE VOICE%'),('%NORTH AMERICAN FUL%'),('%UNITED SUPPORT%'),('%POLITICAL RESPONSE%'),
  ('%OPTICAL MARKETING%'),('%VENDOR SYSTEM%'),('%ACTION COMMITTEE MARKETING%'),('%POLITICAL FUNDRAISING GROUP%'),('%POLITICAL MARKETING SERV%'),('%CAPITAL VENDOR%'),('%UNIQ TECH%')),
b AS (SELECT DISTINCT b.EIN, UPPER(RECIPIENT_NAME) r, EXPENDITURE_DATE d, EXPENDITURE_AMOUNT a, p.pat FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES b JOIN p ON UPPER(b.RECIPIENT_NAME) LIKE p.pat)
SELECT pat, ROUND(SUM(IFF(EIN IN (SELECT EIN FROM g),a,0))/1e6,2) from19_m, ROUND(SUM(IFF(EIN NOT IN (SELECT EIN FROM g),a,0))/1e6,3) others_m,
  ROUND(100*SUM(IFF(EIN IN (SELECT EIN FROM g),a,0))/SUM(a),1) pct19, COUNT(DISTINCT IFF(EIN NOT IN (SELECT EIN FROM g),EIN,NULL)) other_eins,
  LEFT(LISTAGG(DISTINCT IFF(EIN NOT IN (SELECT EIN FROM g), r, NULL), ' | '),160) other_spellings
FROM b GROUP BY pat ORDER BY from19_m DESC
